/* Persistent SVG nodes + cancellable interpolation keep model changes smooth. */
const ModelLab=(()=>{
let raf=0,svg=null,current=[],target=[],playing=false,last=0,phase=0,kind='',count=1,level=0,token=0;
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
const colors=['#49775c','#b6ce79','#c48e52','#6c9ba1'];
const get=s=>document.querySelector(s);
const put=(s,t)=>{const e=get(s);if(e)e.innerHTML=t};
const attr=(e,k,v)=>e?.setAttribute(k,v);
const dot=(x,y,r=10,c=colors[0],a=1)=>[x,y,r,a];
function stop(){cancelAnimationFrame(raf);raf=0;playing=false;token++;svg=null;current=[];target=[]}
function nodes(n){svg.innerHTML=`<g id="model-links"></g><g id="model-dots">${Array.from({length:n},(_,i)=>`<circle id="md${i}" r="10" fill="${colors[i%4]}"/>`).join('')}</g><g id="model-extra"></g>`;current=Array.from({length:n},()=>dot(300,140,1,colors[0],0));target=current.map(p=>[...p])}
function linksHTML(p,chainCount,offset=0){return Array.from({length:Math.max(0,chainCount-1)},(_,i)=>{let a=p[offset+i],b=p[offset+i+1];return `<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${offset?'#b6ce79':'#6b8851'}" stroke-width="5" stroke-linecap="round" opacity="${Math.min(a[3],b[3])}"/>`}).join('')}
function paint(){if(!svg)return;if(kind==='water'){waterPaint(phase);return}current.forEach((p,i)=>{let e=get('#md'+i);attr(e,'cx',p[0]);attr(e,'cy',p[1]);attr(e,'r',p[2]);attr(e,'opacity',p[3])});if(kind==='protein')put('#model-links',linksHTML(current,28)+linksHTML(current,28,28));if(kind==='building')put('#model-links',linksHTML(current,8));if(kind==='families')familyLinks()}
function frame(now){if(!svg||!svg.isConnected){raf=0;return}let dt=Math.min(50,now-(last||now));last=now;phase+=dt/1000;const blend=reduced.matches?1:1-Math.exp(-dt/145);let moving=false;current.forEach((p,i)=>p.forEach((v,j)=>{let diff=target[i][j]-v;if(Math.abs(diff)>.035)moving=true;p[j]=Math.abs(diff)<.035?target[i][j]:v+diff*blend}));paint();if(playing&&!reduced.matches){if(kind==='water')waterPaint(phase);else if(kind==='ph')phPaint(phase);else if(kind==='protein'){let g=get('#model-dots'),l=get('#model-links');let angle=Math.sin(phase*.6)*2;attr(g,'transform',`rotate(${angle} 300 140)`);attr(l,'transform',`rotate(${angle} 300 140)`)}moving=true}if(moving)raf=requestAnimationFrame(frame);else raf=0}
function wake(){if(!raf){last=0;raf=requestAnimationFrame(frame)}}
function aim(p){target=p;if(reduced.matches){current=p.map(x=>[...x]);paint()}else wake()}
function toggle(){playing=!playing;let b=get('#motion');if(b){b.textContent=playing?'Pause motion':'Play motion';b.setAttribute('aria-pressed',playing)}if(!playing&&kind==='protein'){attr(get('#model-dots'),'transform','');attr(get('#model-links'),'transform','')}wake()}
function mount(id){stop();kind=id;const slot=get('#model-slot');if(!slot)return;const titles={water:['Water that moves','Bring the molecules closer. The slightly positive H end is attracted to a slightly negative O end.'],ph:['See the pH change','Move the slider. Lower pH means more hydrogen ions (H⁺). Each pH step is a tenfold change.'],building:['Build it. Break it. Follow the water.','Watch a small building block join the chain, or use water to split one off.'],families:['Meet the four molecule families','Switch families to see a simple sketch of their different shapes.'],protein:['Watch a protein change shape','Keep your eye on the beads. Their order stays the same as the chain folds.']};let [title,desc]=titles[id]||titles.water;let controls='';if(id==='water')controls=`<label for="distance">Molecules: closer ↔ farther <input id="distance" type="range" min="0" max="100" value="35" oninput="ModelLab.water()"></label><label><input id="charges" type="checkbox" checked onchange="ModelLab.water()"> Show partial charges</label>`;if(id==='ph')controls=`<label for="ph">pH <input id="ph" type="range" min="0" max="14" value="7" oninput="ModelLab.ph()"></label>`;if(id==='building')controls=`<button id="join" class="btn" onclick="ModelLab.chain(1)">Join a block</button><button id="split" class="btn light" onclick="ModelLab.chain(-1)">Split a block off</button><button class="btn light" onclick="ModelLab.chain(0)">Reset</button>`;if(id==='families')controls=`<label for="family">Family <select id="family" onchange="ModelLab.family()"><option>Carbohydrates</option><option>Lipids</option><option>Proteins</option><option>Nucleic acids</option></select></label>`;if(id==='protein')controls=`<div class="tabs">${['1 · Sequence','2 · Local folds','3 · Whole fold','4 · Team of chains','Unfold'].map((n,i)=>`<button id="level${i}" onclick="ModelLab.protein(${i})">${n}</button>`).join('')}</div><button class="btn light" onclick="ModelLab.next()">Next shape →</button>`;slot.innerHTML=`<section class="model animated-model"><span class="eyebrow">MOVE IT · NOTICE IT · EXPLAIN IT</span><h3>${title}</h3><p>${desc}</p><div class="controls">${controls}</div><div class="model-stage"><svg id="moving-model" viewBox="0 0 600 290" role="img" aria-label="${title}: simplified interactive diagram"></svg></div><div class="motion-row">${['water','ph','protein'].includes(id)?'<button id="motion" class="motion-button" aria-pressed="false" onclick="ModelLab.toggle()">Play motion</button>':''}<span class="mini">${reduced.matches?'Reduced motion is on. Changes appear immediately.':'Smooth transitions · use sliders or keyboard arrow keys'}</span></div><div id="model-explain" class="output" aria-live="polite"></div><details><summary>What should I notice?</summary><p id="model-notice"></p></details><p class="mini">Simplified sketch, not to scale. Shapes and motion help explain ideas; they are not exact molecular behavior.</p></section>`;svg=get('#moving-model');if(id==='water'){waterSetup();water()}if(id==='ph'){phSetup();ph()}if(id==='building'){nodes(9);count=1;chain(0)}if(id==='families'){nodes(36);family()}if(id==='protein'){nodes(56);protein(0)}if(!reduced.matches&&['water','ph'].includes(id))toggle()}
function waterSetup(){svg.innerHTML=`<line id="attraction" stroke="#bd914b" stroke-width="3" stroke-dasharray="6 7"/><g id="wa">${waterMolecule()}</g><g id="wb">${waterMolecule()}</g><text x="300" y="255" text-anchor="middle" font-size="13">Solid lines: covalent bonds inside each molecule</text>`;current=[dot(175,110),dot(400,155)];target=current.map(p=>[...p])}
function waterMolecule(){return `<path d="M-39 35L0 0L39 35" stroke="#96aa89" stroke-width="11" fill="none"/><circle r="31" fill="#49775c"/><circle cx="-43" cy="39" r="20" fill="#d5e6a1"/><circle cx="43" cy="39" r="20" fill="#d5e6a1"/><text x="0" y="6" text-anchor="middle" fill="white">O</text><text x="-43" y="45" text-anchor="middle">H</text><text x="43" y="45" text-anchor="middle">H</text><g class="charge"><text x="0" y="-43" text-anchor="middle">δ−</text><text x="-62" y="72">δ+</text><text x="45" y="72">δ+</text></g>`}
function water(){let n=+get('#distance').value;target=[dot(190-n*.6,104),dot(340+n*.9,145)];wake();document.querySelectorAll('.charge').forEach(e=>e.style.opacity=get('#charges').checked?'1':'0');put('#model-explain',`<strong>${n<55?'Close enough to show an attraction.':'Farther apart: the attraction gets weaker.'}</strong><br>The dashed line shows a hydrogen bond between molecules. It does not join them into a new molecule.`);put('#model-notice','Water molecules move all the time. Hydrogen bonds form and break as molecules move. The O–H bonds inside each molecule stay together in this model. δ means “slightly,” not a full positive or negative charge.');waterPaint(0)}
function waterPaint(t){let n=+get('#distance').value,bob=playing?Math.sin(t*1.5)*5:0;let a=current[0],b=current[1];attr(get('#wa'),'transform',`translate(${a[0]} ${a[1]+bob})`);attr(get('#wb'),'transform',`translate(${b[0]} ${b[1]-bob})`);const l=get('#attraction');attr(l,'x1',a[0]+43);attr(l,'y1',a[1]+39+bob);attr(l,'x2',b[0]-28);attr(l,'y2',b[1]-bob);attr(l,'opacity',Math.max(.1,1-n/110));}
function phSetup(){svg.innerHTML=`<path d="M200 35V215Q200 235 220 235H380Q400 235 400 215V35" stroke="#8b9e87" stroke-width="4" fill="none"/><path id="liquid" d="M204 100Q230 94 260 100T320 100T396 100V215Q396 231 380 231H220Q204 231 204 215Z" fill="#88b976"/><g id="ions">${Array.from({length:16},(_,i)=>`<g id="ion${i}"><circle r="12" fill="#fff" fill-opacity=".75"/><text y="4" text-anchor="middle" font-size="10" fill="#284d3b">H⁺</text></g>`).join('')}</g><text id="phbig" x="300" y="66" text-anchor="middle" font-size="25" fill="#284d3b"></text><text x="300" y="270" text-anchor="middle" font-size="12">Fewer / more H⁺ icons = a trend, not a literal particle count</text>`}
function ph(){let n=+get('#ph').value,color=n<7?`hsl(${10+n*8} 55% 66%)`:n===7?'#88b976':`hsl(${170+(n-7)*12} 38% 66%)`;attr(get('#liquid'),'fill',color);put('#phbig',`pH ${n}`);let visible=Math.max(1,Math.round(16-n));for(let i=0;i<16;i++)attr(get('#ion'+i),'opacity',i<visible?1:0);phPaint(phase);put('#model-explain',`<strong>${n<7?'Acidic':n>7?'Basic':'Neutral at about 25°C'}</strong><br>${n<7?`${(10**(7-n)).toLocaleString()} times more H⁺ than pH 7.`:n>7?`${(10**(n-7)).toLocaleString()} times less H⁺ than pH 7.`:'Use pH 7 as your comparison point.'} Lower number → more H⁺. A one-step change → 10 times.`);put('#model-notice','Try pH 4, then pH 6. pH 4 has 100 times more H⁺. The liquid colors illustrate the pH scale; real colors depend on which indicator you use. Clear liquids can be acidic or basic too.')}
function phPaint(t){for(let i=0;i<16;i++){let x=225+(i%4)*49+Math.sin(t*.65+i)*5,y=120+Math.floor(i/4)*28+Math.cos(t*.8+i)*4;attr(get('#ion'+i),'transform',`translate(${x} ${y})`)}}
function chain(d){let old=count;if(d===0)count=1;else count=Math.max(1,Math.min(8,count+d));let p=Array.from({length:8},(_,i)=>dot(i<count?65+i*65:540,140,20,colors[0],i<count?1:0));p.push(dot(d>0?Math.min(520,65+(count-1)*65):300,d>0?55:140,13,colors[0],0));let moved=count!==old;current[8]=dot(d>0?Math.min(520,65+(count-1)*65):300,d>0?140:55,13,colors[0],moved?1:0);aim(p);get('#join').disabled=count===8;get('#split').disabled=count===1;put('#model-explain',`<strong>${count} building block${count===1?'':'s'} · ${count-1} link${count===2?'':'s'}</strong><br>${d>0&&moved?'A block joins. Water is released (dehydration synthesis).':d<0&&moved?'Water is used to break a link (hydrolysis).':'Start with one block. Add another to make a link.'}<br>Building this chain from separate blocks releases ${count-1} water molecule${count===2?'':'s'} in our simple model.`);put('#model-extra',`<text x="300" y="245" text-anchor="middle" font-size="13">${moved?(d>0?'Joining → water out':'Splitting → water in'):'A monomer is one building block.'}</text><text id="waterword" x="300" y="40" text-anchor="middle" font-size="15">${moved?'H₂O':''}</text>`);attr(get('#md8'),'fill','#78b7d0');put('#model-notice','Count the links, not just the blocks. Four blocks in one straight chain have three links. Joining releases water; splitting uses water. The blue dot follows the water, not an extra monomer.')}
function family(){let n=get('#family').selectedIndex;let pts=Array.from({length:36},(_,i)=>dot(300,140,8,colors[0],0));if(n===0){for(let i=0;i<18;i++){let ring=Math.floor(i/6),a=(i%6)*Math.PI/3;pts[i]=dot(125+ring*175+Math.cos(a)*45,140+Math.sin(a)*45,12,colors[0],1)}}if(n===1){for(let i=0;i<4;i++)pts[i]=dot(130,80+i*35,12,colors[0],1);for(let i=4;i<25;i++){let tail=Math.floor((i-4)/7),j=(i-4)%7;pts[i]=dot(175+j*48,90+tail*50+(j%2)*10,10,colors[0],1)}}if(n===2){for(let i=0;i<28;i++)pts[i]=dot(300+Math.cos(i*.7)*(50+i*2),140+Math.sin(i*.7)*65,9,colors[0],1)}if(n===3){for(let i=0;i<36;i++){let side=i%2,j=Math.floor(i/2);pts[i]=dot(80+j*26,140+(side?1:-1)*Math.cos(j*.35)*55,7,colors[0],1)}}aim(pts);let data=[['Carbohydrates','Sugar blocks can link into chains.','Fuel, energy storage, or plant support.','Glucose = one sugar. Starch = many sugars.'],['Lipids','This sketch shows one glycerol backbone with three fatty acid tails.','Long-term energy storage. Other lipids help build membranes.','A triglyceride is not a chain of repeating monomers.'],['Proteins','Amino acid blocks make a chain that folds.','Different shapes do different jobs in cells.','Enzymes, transport proteins, and structural proteins are examples.'],['Nucleic acids','Nucleotide blocks make DNA or RNA. This ladder is a DNA sketch.','Store and help use genetic information.','Each nucleotide has a sugar, phosphate, and base.']][n];put('#model-explain',`<strong>${data[0]}</strong><br>${data[1]}<br><b>Job:</b> ${data[2]}<br>${data[3]}`);put('#model-extra',`<text x="300" y="265" text-anchor="middle" font-size="13">${['Sugar rings','Backbone + three tails','One folded amino acid chain','Two DNA strands'][n]}</text>`);put('#model-notice','These sketches help compare shapes. Switching families replaces one example with another; it does not mean one kind of molecule turns into another. Colors are just guides, not real molecule colors.')}
function familyLinks(){let n=get('#family').selectedIndex,p=current;const line=(i,j)=>`<line x1="${p[i][0]}" y1="${p[i][1]}" x2="${p[j][0]}" y2="${p[j][1]}" stroke="#78936c" stroke-width="3" opacity="${Math.min(p[i][3],p[j][3])}"/>`;let out='';if(n===0){for(let r=0;r<3;r++){for(let i=0;i<6;i++)out+=line(r*6+i,r*6+(i+1)%6);if(r<2)out+=line(r*6, (r+1)*6+3)}}if(n===1){for(let i=0;i<3;i++)out+=line(i,i+1);for(let t=0;t<3;t++){out+=line(t+1,4+t*7);for(let j=0;j<6;j++)out+=line(4+t*7+j,5+t*7+j)}}if(n===2)out=linksHTML(p,28);if(n===3){for(let i=0;i<34;i+=2){out+=line(i,i+2)+line(i+1,i+3)+line(i,i+1)}out+=line(34,35)}put('#model-links',out)}
function protein(n){level=n;document.querySelectorAll('[id^=level]').forEach((e,i)=>{e.classList.toggle('active',i===n);e.setAttribute('aria-pressed',String(i===n))});let pts=Array.from({length:56},(_,i)=>{let j=i%28,second=i>=28,x=45+j*18.5,y=135;if(n===1)y+=Math.sin(j*.8)*44;if(n===2){x=300+Math.cos(j*.65)*(50+j*1.8);y=135+Math.sin(j*.65)*70}if(n===3){x=170+(second?255:0)+Math.cos(j*.65)*78;y=135+Math.sin(j*.65)*64}if(n===4)y+=Math.sin(j*.38)*18;return dot(x,y,7,colors[0],second?(n===3?1:0):1)});aim(pts);put('#model-explain',[
'<strong>1. Primary = order.</strong><br>Like beads on a string: which amino acid comes first, next, and last? Peptide bonds connect the beads.',
'<strong>2. Secondary = small folds.</strong><br>Parts of the chain form coils or sheets. Hydrogen bonds between backbone groups help hold these patterns.',
'<strong>3. Tertiary = one chain’s whole shape.</strong><br>Side chains (R groups) interact and help the chain fold. The final shape helps the protein do its job.',
'<strong>4. Quaternary = a team.</strong><br>Two or more folded chains work together. Not every protein needs a team.',
'<strong>Denatured = the useful fold is lost.</strong><br>Heat or extreme pH can change the shape. The amino acid order usually stays the same, but the protein may no longer work.'
][n]);put('#model-extra',`<text x="300" y="265" text-anchor="middle" font-size="13">${n===3?'Two chains shown':n===4?'Unfolded does not mean cut into pieces':'One chain shown'} · colors track the same beads</text>`);put('#model-notice','Click through the shapes, then choose Unfold. The beads move but stay connected in the same order. This is a shape analogy, not an exact folding pathway. A second chain appears only for the team example.')}
reduced.addEventListener('change',()=>{if(reduced.matches){playing=false;let b=get('#motion');if(b){b.textContent='Play motion';b.setAttribute('aria-pressed','false')}if(target.length){current=target.map(p=>[...p]);paint()}}});
return {mount,stop,toggle,water,ph,chain,family,protein,next:()=>protein((level+1)%5)};
})();
